import java.util.TimeZone;
import org.junit.*;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class DateUtils_add_TriageGen0Test {

    @Rule
    public ExpectedException thrown = ExpectedException.none();







    @Test
    public void testAdd_Years() {
        Calendar cal = Calendar.getInstance();
        cal.set(2020, Calendar.FEBRUARY, 29, 10, 0, 0); // Leap year
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        // Adding 1 year to Feb 29 should result in Feb 28 in a non-leap year
        Date result = DateUtils.add(date, Calendar.YEAR, 1);

        Calendar resultCal = Calendar.getInstance();
        resultCal.setTime(result);
        assertEquals(2021, resultCal.get(Calendar.YEAR));
        assertEquals(Calendar.FEBRUARY, resultCal.get(Calendar.MONTH));
        assertEquals(28, resultCal.get(Calendar.DAY_OF_MONTH));
    }




}

